#define main ensemble_main
#include "ensemble.cpp"
#undef main
int main(int argc,char**argv){if(argc!=8)return 2;int order=stoi(argv[2]),n=stoi(argv[3]);size_t M=stoull(argv[4]);unsigned long long seed=stoull(argv[5]);int B=stoi(argv[6]),P=stoi(argv[7]);ifstream in(argv[1],ios::binary);vector<double>p(26+676+17576);in.read((char*)p.data(),p.size()*8);if(!in)return 4;array<Alias,703>tab;tab[0].init(p.data());for(int h=0;h<26;h++)tab[1+h].init(p.data()+26+26*h);for(int h=0;h<676;h++)tab[27+h].init(p.data()+26+676+26*h);auto row=[&](int t,int a,int b){return order==0||t==0?0:order==1||t==1?1+b:27+26*a+b;};auto probs=[&](int h){return h==0?p.data():h<27?p.data()+26+26*(h-1):p.data()+702+26*(h-27);};mt19937_64 outer(seed),inner(seed+1000000007);long double sum=0,sum2=0,threshold=0,entropy=0,qxsum=0;
for(int sample=0;sample<B;sample++){vector<int>x(n),s(n);array<int,26>map;map.fill(-1);int d=0;double qx=1;for(int t=0;t<n;t++){int h=row(t,t>=2?x[t-2]:0,t>=1?x[t-1]:0);x[t]=tab[h].sample(outer);qx*=probs(h)[x[t]];if(map[x[t]]<0)map[x[t]]=d++;s[t]=map[x[t]];}
long double total=0;for(int particle=0;particle<P;particle++){array<int,26>assign;assign.fill(-1);array<bool,26>used{};int nd=0,last=0,prev=0;double weight=1;bool same=true;for(int t=0;t<n;t++){int h=row(t,prev,last);const double* pr=probs(h);int c=assign[s[t]];if(c>=0){weight*=pr[c];}else{double z=1;for(int j=0;j<nd;j++)z-=pr[assign[j]];if(z<=1e-15){weight=0;break;}weight*=z;do{c=tab[h].sample(inner);}while(used[c]);assign[s[t]]=c;used[c]=true;nd++;}if(weight==0)break;same=same&&(c==x[t]);prev=last;last=c;}if(!same)total+=weight;}
double other=(double)(total/P);other=max(0.,min(1.,other));double qs=min(1.,other+qx);double value=other==1?0:exp((M-1)*log1p(-other));sum+=value;sum2+=value*value;threshold+=qs<1./M;entropy+=-log2(qs);qxsum+=qx;
}
double mean=sum/B,se=sqrt(max((long double)0,(sum2-B*mean*mean)/(B-1)/B));cout<<setprecision(15)<<order<<','<<n<<','<<M<<','<<seed<<','<<B<<','<<P<<','<<mean<<','<<se<<','<<threshold/B<<','<<entropy/B<<','<<qxsum/B<<'\n';}
